export interface LogosProps {
	name?: string;
	size?: number;
	color?: string;
	margin?: number | string;
}

export function Logo(props: Readonly<LogosProps>) {
	const { name, size, color, margin } = props;
	switch (name) {
		case 'rc':
			return <RcLogo size={size} color={color} margin={margin} />;
		case 'slice':
			return <SliceLogo size={size} color={color} margin={margin} />;
		case 'uris-design':
			return <UrisDesignLogo size={size} color={color} margin={margin} />;
		case 'godaddy':
			return <GodaddyLogo size={size} color={color} margin={margin} />;
		case 'paypal':
			return <PayPalLogo size={size} color={color} margin={margin} />;
		case 'framer':
			return <FramerLogo size={size} color={color} margin={margin} />;
		case 'unreal':
			return <UnrealEngineLogo size={size} color={color} margin={margin} />;
		case 'gp':
			return <GPLogo size={size} color={color} margin={margin} />;
		default:
			return null;
	}
}

